<script lang="ts">
 import {DBState} from '../../ts/stores.svelte';
 import {createBlankChar} from '../../ts/characters';
 import {importCharacter,exportCharacterCard} from '../../ts/characterCards';
 import {checkCharOrder} from '../../ts/globalApi.svelte';
 import {chatState,selectCharacter} from '../bridge.svelte';
 import {notify} from '../state.svelte';
 let editing=$state(''),name=$state(''),description=$state(''),greeting=$state(''),working=$state(false);
 function edit(id:string){const character=DBState.db.characters.find(c=>c.chaId===id);if(!character)return;editing=id;name=character.name;description=character.type==='character'?character.desc:'';greeting=character.type==='character'?character.firstMessage:'';}
 async function perform(action:()=>Promise<unknown>){if(working)return;working=true;try{await action();}catch(e){notify(String(e).replace(/^Error: /,''));}finally{working=false;}}
 function save(){if(!name.trim()){notify('请填写角色名字。');return;}if(chatState.busy)return;const character=DBState.db.characters.find(c=>c.chaId===editing);if(character){character.name=name.trim();if(character.type==='character'){character.desc=description;character.firstMessage=greeting;}}else{const next=createBlankChar();next.name=name.trim();next.desc=description;next.firstMessage=greeting;DBState.db.characters.push(next);checkCharOrder();}editing='';name='';description='';greeting='';notify('角色已保存。');}
</script>
<section class="xy-panel character-manager"><h2>陪伴角色</h2><p class="quiet-note">角色、群聊和历史对话保留在兼容存档中；可导入已有角色卡。</p><div class="character-rows">{#each DBState.db.characters as character,index}<div><span><strong>{character.name}</strong><small>{character.type==='group'?'群聊':'陪伴角色'} · {character.chats.length} 段对话</small></span><div><button class="text-button" disabled={chatState.busy} onclick={()=>void selectCharacter(index).then(()=>location.hash='/chat')}>聊聊</button><button class="text-button" disabled={chatState.busy} onclick={()=>edit(character.chaId)}>编辑</button>{#if character.type==='character'}<button class="text-button" disabled={working||chatState.busy} onclick={()=>perform(()=>exportCharacterCard(structuredClone($state.snapshot(character)),'json',{spec:'v3'}))}>导出角色卡</button>{/if}</div></div>{/each}</div><div class="xy-actions"><button class="xy-btn" disabled={working||chatState.busy} onclick={()=>perform(importCharacter)}>导入角色卡</button><button class="xy-btn" onclick={()=>{editing='new';name='';description='';greeting='你好，很高兴见到你。';}}>添加陪伴角色</button></div>
{#if editing}<form onsubmit={e=>{e.preventDefault();save();}}><label for="character-name">角色名字</label><input id="character-name" maxlength="80" required bind:value={name}/><label for="character-description">角色设定</label><textarea id="character-description" rows="3" maxlength="20000" bind:value={description}></textarea><label for="character-greeting">初次问候</label><textarea id="character-greeting" rows="2" maxlength="4000" bind:value={greeting}></textarea><div class="xy-actions"><button class="xy-btn primary" disabled={chatState.busy}>保存角色</button><button class="xy-btn" type="button" onclick={()=>editing=''}>取消编辑</button></div></form>{/if}</section>
<style>.character-manager{grid-column:1/-1}.character-rows{margin:18px 0 12px;display:grid;gap:12px}.character-rows>div{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-bottom:12px;border-bottom:1px solid var(--xy-border)}.character-rows small{display:block;color:var(--xy-secondary);font-size:12px}.character-rows>div>div{display:flex;flex-wrap:wrap;gap:14px}.character-rows button{min-height:44px}form{max-width:720px;margin-top:24px}form label{display:block;margin:12px 0 6px}form input,form textarea{width:100%;border:1px solid var(--xy-border);border-radius:8px;background:var(--xy-panel);padding:10px;color:var(--xy-ink)}@media(max-width:600px){.character-rows>div{align-items:start;flex-direction:column;gap:6px}}</style>
